BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path=public,extensions,pg_temp;
SELECT plan(19);
SELECT has_table('public','entity_codes','human addresses exist');
SELECT has_table('public','entity_code_counters','transactional counters exist');
SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('public.entity_codes'::regclass,'public.entity_code_counters'::regclass)),'both tables enable RLS');
SELECT ok(NOT has_table_privilege('authenticated','public.entity_codes','INSERT,UPDATE,DELETE'),'members cannot rename addresses');
SELECT ok(NOT has_table_privilege('pricing_backend','public.entity_codes','INSERT,UPDATE,DELETE'),'pricing cannot rewrite addresses');
SELECT ok(NOT has_table_privilege('documentary_backend','public.entity_code_counters','SELECT,INSERT,UPDATE,DELETE'),'trusted writer uses function only');
SELECT ok(NOT has_function_privilege('authenticated','private.assign_entity_code(uuid,text,uuid)','EXECUTE'),'members cannot allocate codes');
SELECT ok(has_function_privilege('documentary_backend','private.assign_entity_code(uuid,text,uuid)','EXECUTE'),'domain transaction can reserve before sealing');
SELECT ok(NOT has_function_privilege('anon','private.entity_code(uuid,text,uuid,text)','EXECUTE'),'anonymous reads denied');
SELECT has_trigger('public','orders','assign_order_entity_code','orders assign on insert');
SELECT has_trigger('public','inventory_remnants','assign_remnant_entity_code','remnants assign on insert');
SELECT has_trigger('public','order_receipts','assign_receipt_entity_code','receipts assign on insert');
SELECT has_trigger('public','entity_codes','entity_code_immutable','immutable identities guarded');
INSERT INTO public.tenancy_organizations(id,name,tax_id) VALUES('19700000-0000-4000-8000-000000000001','P02 pgTAP','P02-197');
SELECT is(private.assign_entity_code('19700000-0000-4000-8000-000000000001','OC','19700000-0000-4000-8000-000000000002'),'OC-000001','first human address');
SELECT is(private.assign_entity_code('19700000-0000-4000-8000-000000000001','OC','19700000-0000-4000-8000-000000000002'),'OC-000001','replay never advances');
SELECT throws_ok($$UPDATE public.entity_codes SET code='OC-999999' WHERE org_id='19700000-0000-4000-8000-000000000001'$$,'42501','entity_code_immutable','cannot rename');
SELECT throws_ok($$DELETE FROM public.entity_codes WHERE org_id='19700000-0000-4000-8000-000000000001'$$,'42501','entity_code_immutable','cannot delete');
SELECT is(private.assign_entity_code('19700000-0000-4000-8000-000000000001','RT','19700000-0000-4000-8000-000000000002'),'RT-000001','different kinds independent');
SELECT is(private.assign_entity_code('19700000-0000-4000-8000-000000000001','OC','19700000-0000-4000-8000-000000000003'),'OC-000002','no reuse');
SELECT * FROM finish();
ROLLBACK;
